(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-4-anatomical-position-relationships-quiz-version-2"]={"title":"Anatomical Position & Relationships — Anatomy Exam 4 — Set 2","category":"Anatomy","exam":"Exam 4","sem":"summer-1-2026","questions":[{"q":"The brachialis lies how relative to the biceps brachii in the arm?","choices":["Superficial to the biceps brachii","Deep to the biceps brachii","Lateral to the biceps brachii","Proximal to the biceps brachii"],"answer":1,"exp":"The brachialis lies beneath the biceps brachii on the anterior arm, so it is deep to the biceps. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In the abdominal wall, the external oblique lies how relative to the transversus abdominis?","choices":["Superficial to the transversus abdominis","Deep to the transversus abdominis","Inferior to the transversus abdominis","Medial to the transversus abdominis"],"answer":0,"exp":"The external oblique is the outermost flat abdominal muscle and the transversus abdominis the innermost, so the external oblique is superficial to the transversus abdominis. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The erector spinae muscles lie how relative to the overlying trapezius?","choices":["Superficial to the trapezius","Lateral to the trapezius","Superior to the trapezius","Deep to the trapezius"],"answer":3,"exp":"The erector spinae are deep intrinsic back muscles lying beneath the superficial trapezius, so they are deep to the trapezius. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'medial' means a structure is located how?","choices":["Farther from the midline","Nearer to the body surface","Nearer to the head","Nearer to the midline of the body"],"answer":3,"exp":"Medial means closer to the median plane that divides the body into right and left halves. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'lateral' means a structure is located how?","choices":["Nearer to the midline of the body","Farther from the midline of the body","Nearer to the back of the body","Nearer to the trunk of the body"],"answer":1,"exp":"Lateral means away from the midline, toward the side of the body. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The two parietal bones are located how relative to the frontal bone?","choices":["Posterior to the frontal bone","Anterior to the frontal bone","Inferior to the frontal bone","Deep to the frontal bone"],"answer":0,"exp":"The parietal bones form the top and sides of the skull behind the frontal bone, so they are posterior to the frontal bone. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The maxilla is located how relative to the mandible?","choices":["Superior to the mandible","Inferior to the mandible","Posterior to the mandible","Lateral to the mandible"],"answer":0,"exp":"The maxilla forms the upper jaw above the mandible, so it is superior to the mandible. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The greater tubercle of the humerus is located how relative to the lesser tubercle?","choices":["Medial to the lesser tubercle","Distal to the lesser tubercle","Lateral to the lesser tubercle","Deep to the lesser tubercle"],"answer":2,"exp":"On the proximal humerus the greater tubercle lies on the outer (lateral) side and the lesser tubercle on the front, so the greater tubercle is lateral to the lesser tubercle. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The greater trochanter of the femur is located how relative to the lesser trochanter?","choices":["Lateral and superior to the lesser trochanter","Medial and inferior to the lesser trochanter","Directly anterior to the lesser trochanter","Directly deep to the lesser trochanter"],"answer":0,"exp":"The greater trochanter projects from the upper outer femur, while the lesser trochanter sits lower and medial, so the greater trochanter is lateral and superior to the lesser trochanter. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The humerus is located how relative to the radius and ulna?","choices":["Proximal to the radius and ulna","Distal to the radius and ulna","Medial to the radius and ulna","Superficial to the radius and ulna"],"answer":0,"exp":"The humerus is the arm bone nearer the trunk, above the forearm bones, so it is proximal to the radius and ulna. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The patella is located how relative to the distal femur?","choices":["Posterior to the distal femur","Anterior to the distal femur","Medial to the distal femur","Deep to the distal femur"],"answer":1,"exp":"The patella (kneecap) lies over the front of the knee, so it is anterior to the distal femur. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The iliac crest is located how relative to the ischial tuberosity?","choices":["Inferior to the ischial tuberosity","Anterior to the ischial tuberosity","Superior to the ischial tuberosity","Deep to the ischial tuberosity"],"answer":2,"exp":"The iliac crest is the upper rim of the hip bone, while the ischial tuberosity is the lower sitting bone, so the iliac crest is superior to the ischial tuberosity. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The pubic symphysis is located how relative to the sacrum?","choices":["Posterior to the sacrum","Anterior to the sacrum","Superior to the sacrum","Lateral to the sacrum"],"answer":1,"exp":"The pubic symphysis lies at the front of the pelvis, while the sacrum lies at the back, so the pubic symphysis is anterior to the sacrum. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"A person lying face down, in the prone position, has their anterior surface facing which way?","choices":["Upward, toward the ceiling","Toward the left side","Downward, toward the ground","Toward the head end"],"answer":2,"exp":"In the prone position the body lies face down, so the anterior (front) surface faces downward toward the ground. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"A person lying face up, in the supine position, has their anterior surface facing which way?","choices":["Downward, toward the ground","Upward, toward the ceiling","Toward the right side","Toward the feet end"],"answer":1,"exp":"In the supine position the body lies face up, so the anterior (front) surface faces upward toward the ceiling. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"Which plane divides the body into anterior (front) and posterior (back) portions?","choices":["The sagittal plane","The transverse plane","The frontal (coronal) plane","The oblique plane"],"answer":2,"exp":"The frontal, or coronal, plane runs vertically and divides the body into anterior and posterior portions. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"Which plane divides the body into right and left portions?","choices":["The frontal (coronal) plane","The transverse plane","The horizontal plane","The sagittal plane"],"answer":3,"exp":"The sagittal plane runs vertically front to back and divides the body into right and left portions. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"Which plane divides the body into superior (upper) and inferior (lower) portions?","choices":["The sagittal plane","The frontal (coronal) plane","The median plane","The transverse plane"],"answer":3,"exp":"The transverse (horizontal) plane divides the body into superior and inferior portions. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'anterior' (ventral) means a structure is located how?","choices":["Nearer to the back of the body","Nearer to the head","Nearer to the front of the body","Nearer to the midline"],"answer":2,"exp":"Anterior, or ventral, means toward the front surface of the body. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The directional term 'posterior' (dorsal) means a structure is located how?","choices":["Nearer to the back of the body","Nearer to the front of the body","Nearer to the feet","Nearer to the surface"],"answer":0,"exp":"Posterior, or dorsal, means toward the back surface of the body. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"Two structures on the same side of the body are described by which term?","choices":["Contralateral","Bilateral","Intermediate","Ipsilateral"],"answer":3,"exp":"Structures on the same side of the body are said to be ipsilateral to each other. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"Two structures on opposite sides of the body are described by which term?","choices":["Ipsilateral","Unilateral","Contralateral","Superficial"],"answer":2,"exp":"Structures on opposite sides of the body are said to be contralateral to each other. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"In anatomical position, the spinous process of a vertebra projects in which direction from the body?","choices":["Anteriorly","Superiorly only","Laterally on each side","Posteriorly"],"answer":3,"exp":"The spinous process projects backward (posteriorly) from the vertebral arch, opposite the anterior body. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The transverse processes of a vertebra project in which direction from the vertebral arch?","choices":["Directly anteriorly","Directly posteriorly","Directly inferiorly","Laterally on each side"],"answer":3,"exp":"The transverse processes project laterally to each side of the vertebral arch for muscle and rib attachment. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The toes (phalanges of the foot) are located how relative to the tarsal bones?","choices":["Proximal to the tarsal bones","Distal to the tarsal bones","Medial to the tarsal bones","Superior to the tarsal bones"],"answer":1,"exp":"The toe phalanges lie at the far end of the foot, farther from the ankle than the tarsals, so they are distal to the tarsal bones. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The occipital bone is located how relative to the two parietal bones?","choices":["Posterior and inferior to the parietal bones","Anterior and superior to the parietal bones","Directly lateral to the parietal bones","Directly deep to the parietal bones"],"answer":0,"exp":"The occipital bone forms the back and base of the skull behind and below the parietal bones, so it is posterior and inferior to them. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The first rib is located how relative to the twelfth rib?","choices":["Inferior to the twelfth rib","Superior to the twelfth rib","Anterior to the twelfth rib","Deep to the twelfth rib"],"answer":1,"exp":"The first rib is at the top of the thoracic cage and the twelfth at the bottom, so the first rib is superior to the twelfth rib. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The shoulder is located how relative to the hand?","choices":["Distal to the hand","Proximal to the hand","Medial to the hand","Deep to the hand"],"answer":1,"exp":"The shoulder is nearest the trunk and the hand farthest, so the shoulder is proximal to the hand. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The trapezius is located how relative to the deep rhomboid muscles?","choices":["Superficial to the rhomboid muscles","Deep to the rhomboid muscles","Inferior to the rhomboid muscles","Lateral to the rhomboid muscles"],"answer":0,"exp":"The trapezius is a superficial back muscle overlying the deeper rhomboids, so it is superficial to the rhomboid muscles. — Directional & positional terminology applied to Anatomy Exam 4 structures"},{"q":"The skeletal muscles of the arm are located how relative to the overlying skin?","choices":["Superficial to the skin","Distal to the skin","Deep to the skin","Medial to the skin"],"answer":2,"exp":"The skin is the outermost covering, so the arm muscles beneath it are deep to the skin. — Directional & positional terminology applied to Anatomy Exam 4 structures"}]};
